   <a class="skip-link" href="#support-form">Skip to the support form</a>

   <main id="main-content">
     <div class="page-shell">
       <section class="hero" aria-labelledby="page-title">
         <p class="eyebrow">Support</p>
         <h1 id="page-title">Contact our team</h1>
         <p>
           Send us your details and we&apos;ll get back to you as soon as we can.
           Full name and email are required so we can respond.
         </p>
       </section>

       <section class="form-card" aria-labelledby="support-form-title">
         <h2 id="support-form-title" class="eyebrow" style="margin-top:0;">Message details</h2>
         <p class="form-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>

         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
             <input
               id="full-name"
               name="fullName"
               type="text"
               autocomplete="name"
               required
               aria-describedby="full-name-error"
             />
             <p class="error-message" id="full-name-error" hidden aria-live="polite">Error: Enter your full name.</p>
           </div>

           <div class="form-field">
             <label for="email-address">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
             <input
               id="email-address"
               name="emailAddress"
               type="email"
               autocomplete="email"
               required
               aria-describedby="email-address-error"
             />
             <p class="error-message" id="email-address-error" hidden aria-live="polite">Error: Enter a valid email address, like name@example.com.</p>
           </div>

           <div class="form-field">
             <label for="phone-number">Phone number</label>
             <input
               id="phone-number"
               name="phoneNumber"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-number-help phone-number-error"
             />
             <p class="help-text" id="phone-number-help">Optional. Use a number like +1 555-123-4567 or 555 123 4567.</p>
             <p class="error-message" id="phone-number-error" hidden aria-live="polite">Error: Enter a valid phone number using digits, spaces, parentheses, plus signs, or hyphens.</p>
           </div>

           <button type="submit">Send message</button>
         </form>
       </section>
     </div>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fields = {
       fullName: {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate(value) {
           return value.trim().length > 0;
         },
       },
       emailAddress: {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate(value) {
           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
         },
       },
       phoneNumber: {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate(value) {
           if (value.trim() === '') {
             return true;
           }

           return /^[+]?[\d\s().-]{7,}$/.test(value.trim()) && /\d/.test(value);
         },
       },
     };

     function setFieldState(field, isValid) {
       const { input, error } = field;
       if (isValid) {
         input.removeAttribute('aria-invalid');
       } else {
         input.setAttribute('aria-invalid', 'true');
       }
       error.hidden = isValid;
     }

     function validateField(field) {
       const isValid = field.validate(field.input.value);
       setFieldState(field, isValid);
       return isValid;
     }

     function getFirstInvalidField() {
       return Object.values(fields).find((field) => !field.validate(field.input.value));
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener('blur', () => {
         validateField(field);
       });

       field.input.addEventListener('input', () => {
         if (field.input.getAttribute('aria-invalid') === 'true') {
           validateField(field);
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       Object.values(fields).forEach((field) => validateField(field));
       const invalidField = getFirstInvalidField();
       const isFormValid = !invalidField;

       if (!isFormValid && invalidField) {
         invalidField.input.focus();
         return;
       }

       form.reset();
       Object.values(fields).forEach((field) => {
         setFieldState(field, true);
       });
     });
